// ---------------------------------------------------------------------------- strings
PL.len = (s) => (s === undefined ? undefined : PL.str(s).length);
const asciiLower = (s) => s.replace(/[A-Z]+/g, (m) => m.toLowerCase());
const asciiUpper = (s) => s.replace(/[a-z]+/g, (m) => m.toUpperCase());
