PL.lc = (x) => { const s = PL.str(x); return isWide(s) ? s.toLowerCase() : asciiLower(s); };
PL.uc = (x) => { const s = PL.str(x); return isWide(s) ? s.toUpperCase() : asciiUpper(s); };
PL.lcfirst = (x) => { const s = PL.str(x); return s ? PL.lc(s[0]) + s.slice(1) : s; };
