PL.chr = (n) => {
  n = Math.trunc(PL.num(n));
  if (n < 0 || n > 0x10ffff || !isFinite(n)) return '\uFFFD';
  return n <= 0xffff ? String.fromCharCode(n) : String.fromCodePoint(n);
};
