PL.sprintf = makeSprintf(PL);
const { pack, unpack } = makePack(PL);
PL.pack = pack;
PL.unpack = unpack;
PL.utf8Encode = utf8Encode;

// ---------------------------------------------------------------------------- arrays & hashes
