externals.set('Scalar::Util::blessed', (x) => { const r = PL.ref(x); return r && !['HASH', 'ARRAY', 'CODE', 'SCALAR', 'REF', 'GLOB', 'Regexp'].includes(r) ? r : undefined; });
externals.set('Scalar::Util::reftype', (x) => (x && typeof x === 'object' ? reftype(x) : undefined));
externals.set('Scalar::Util::refaddr', (x) => (x && typeof x === 'object' ? refaddr(x) : undefined));
externals.set('Scalar::Util::looks_like_number', (x) => (/^\s*[-+]?(\d+\.?\d*([eE][-+]?\d+)?|\.\d+([eE][-+]?\d+)?|0[xX][0-9a-fA-F]+|inf(inity)?|nan)\s*$/i.test(PL.str(x)) ? 1 : ''));
PL.isWide = isWide;
PL.RLIST = RLIST;
PL.STUB = STUB;
PL.CLASS = CLASS;

export default PL;
PL.loopOut = (op) => { throw new PerlDie(`Can't "${op}" outside a loop block at (eval) line 1.\n`); };
PL.exportTags = (pkg, which, tags) => {
  const all = pkg.EXPORT_TAGS || {};
  if (!pkg[which]) pkg[which] = [];
  if (!tags.length) tags = Object.keys(all);
  for (const t of tags) for (const sym of all[PL.str(t)] || []) if (!pkg[which].includes(sym)) pkg[which].push(sym);
};
